head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pwcnt = 0;
scwin.loadset = 0;
scwin.rowPosition = 0;
scwin.contnId;
scwin.gRegEmpNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.getCode();
        $c.cm.PanelToGroupBox(panel_Top);
        tbox_mkt_tp.hide();
        filePw.hide();
        label_16.hide();
        btn_input.hide();
        getContnId = $c.frame.path("../").fn_getContnId;
        scwin.contnId = getContnId();
        if (scwin.contnId !== "input") {
            await scwin.read();
            //        showObj(panel_mail, false);
            cbox_mail_yn.setValue(0);
            scwin.iniPicYnSet();
            if (scwin.pwcnt > 0) {
                filePw.show("");
                label_16.show("");
                btn_input.show("");
            }
            if (dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") === js_emp_no) {
                scwin.loadset = 1;
                scwin.iniAtachfFilePwSet();
            }
        } else {
            // 입력 화면 생성
            scwin.setDataHeader();
            await scwin.setSaveHeader();
            tbox_wrtr_emp_nm.setValue(js_emp_nm);
            tbox_reg_dep_nm.setValue(js_dep_nm);
            tbox_wrt_ddtm.setValue($c.ut.cGetToday("yyyy-mm-dd hh:mm:ss"));
            tbox_inq_cnt.setValue("0");
            tbox_mkt_tp.setValue(js_market);
            rdo_creatloc_tp.setValue('01');
            cmb_secu_lvl_tp.setValue('04');
            rdo_creatloc_tp.setValue('01');
            scwin.setChkValue(chb_impt_contn_yn, false);
            dts_KnowlgTp.UseFilter = true;
            dts_KnowlgTp.Filter();
            panel_mail.show("");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30301.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        if (scwin.contnId === "input") {
            await scwin.save();
        } else {
            await scwin.update();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30301.btn_save_onclick" });
    }
};

