/**
 * @method
 * @name grd_fileList_onkeydown
 * @description grd_fileList 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_onkeydown = function() {
    try {
        if (event.keyCode === 13 || event.keyCode === 32) {
            scwin.chHolding();
            return;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30301.grd_fileList_onkeydown" });
    }
};

/**
 * @method
 * @name grd_fileList_OnClick
 * @description grd_fileList 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_fileList_OnClick = async function(row, colid) {
    try {
        if (colid === "filename") {
            if (scwin.contnId !== "input") {
                dts_fileList.setRowPosition(0, 0);
            }
            if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
                if (dts_fileList.getCellData(row, "ATTACH_FILE_PW") !== "" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") !== js_emp_no) {
                    if (dts_fileList.getCellData(row, "ATTACH_FILE_PW") === filePw.getValue()) {
                        dts_fileList.setCellData(row, "PIC_YN", "T");
                        scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
                    } else {
                        filePw.show("");
                        label_16.show("");
                        btn_input.show("");
                        scwin.setFocusedCell(row, 0);
                        if (filePw.getValue() !== "") {
                            await $c.win.alert("비밀번호가 올바르지 않습니다.");
                        } else {
                            await $c.win.alert("비밀번호를 입력해주세요");
                        }
                        filePw.focus();
                    }
                } else {
                    if (dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") === js_emp_no) {
                        scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
                    } else {
                        filePw.setValue("");
                        filePw.hide();
                        label_16.hide();
                        btn_input.hide();
                        scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
                    }
                }
            }
        } else {
            if (scwin.contnId === "input" || dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") === js_emp_no) {
                scwin.copyAttachFilePw();
                if (scwin.pwcnt > 0) {
                    if (rdo_creatloc_tp.getValue() === "01") {
                        filePw.show("");
                        label_16.show("");
                        btn_input.show("");
                    } else {
                        filePw.hide();
                        label_16.hide();
                        btn_input.hide();
                        scwin.iniAttachFilePw();
                    }
                } else {
                    filePw.hide();
                    label_16.hide();
                    btn_input.hide();
                    scwin.iniAttachFilePw();
                }
            } else {
                filePw.setValue("");
            }
        }
        return true;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30301.grd_fileList_OnClick" });
    }
};

/**
 * @method
