        await $c.win.alert('dts_ShareRoomInfo.OnLoadError()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30301.dts_ShareRoomInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ShareRoomInfo_OnLoadCompleted
 * @description dts_ShareRoomInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ShareRoomInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.gRegEmpNo = dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO");
        if (dts_ShareRoomInfo.getCellData(0, "IMPT_CONTN_YN") === 'Y') {
            if (scwin.pwcnt > 0) {
                scwin.setChkValue(chb_impt_contn_yn, true);
            } else {
                scwin.setChkValue(chb_impt_contn_yn, false);
            }
        } else {
            scwin.setChkValue(chb_impt_contn_yn, false);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30301.dts_ShareRoomInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_SecuLvlTp_OnLoadCompleted
 * @description dts_SecuLvlTp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_SecuLvlTp_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.contnId === "input") {
            cmb_secu_lvl_tp.setValue('04');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30301.dts_SecuLvlTp_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name rdo_creatloc_tp_onselchange
 * @description rdo_creatloc_tp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_creatloc_tp_onselchange = function() {
    try {
        // alert(getObjectValue(rdo_creatloc_tp));
        dts_KnowlgTp.UseFilter = true;
        dts_KnowlgTp.Filter();
        cmb_knowlg_tp.trigger("onclick");
        if (scwin.contnId !== "input") {
            filePw.setValue("");
            scwin.iniPicYn();
            filePw.hide();
            label_16.hide();
            btn_input.hide();
            if (rdo_creatloc_tp.getValue() !== "01" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") === js_emp_no) {
                scwin.iniAttachFilePw();
            }
        } else {
            if (rdo_creatloc_tp.getValue() === "01") {
                if (scwin.pwcnt > 0) {
                    filePw.show("");
                    label_16.show("");
                    btn_input.show("");
                }
            } else {
                filePw.hide();
                label_16.hide();
                btn_input.hide();
                scwin.iniAttachFilePw();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30301.rdo_creatloc_tp_onselchange" });
    }
};

/**
 * @method
 * @name dts_KnowlgTp_OnFilter
 * @description Knowlg Tp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_KnowlgTp_OnFilter = function(row) {
    try {
        //  생성처에 따른 지식구분을 가져온다.
        if (rdo_creatloc_tp.getValue() === '01') {
            if (dts_KnowlgTp.getCellData(row, "value").substr(0, 1) === 'A' ||
                dts_KnowlgTp.getCellData(row, "value") === '') {
                return true;
            } else {
                return false;
            }
        } else if (rdo_creatloc_tp.getValue() === '02') {
            if (dts_KnowlgTp.getCellData(row, "value").substr(0, 1) === 'B' ||
                dts_KnowlgTp.getCellData(row, "value") === '') {
                return true;
            } else {
                return false;
            }
        } else {
            return false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30301.dts_KnowlgTp_OnFilter" });
    }
};

/**
 * @method
 * @name img_update_onclick
 * @description 「수정」 클릭 이벤트
