 */
scwin.filePw_onkeyup = function() {
    try {
        if (scwin.contnId !== "input" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") !== js_emp_no) {

        } else {
            scwin.copyAttachFilePw();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30301.filePw_onkeyup" });
    }
};

/**
 * @method
 * @name btn_input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_input_onclick = async function() {
    try {
        if (dts_fileList.getCellData(scwin.rowPosition, "ATTACH_FILE_PW") === filePw.getValue()) {
            if (scwin.contnId !== "input" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") !== js_emp_no) {
                scwin.filedown(dts_fileList.getCellData(scwin.rowPosition, "ATTACH_SEQ"));
            } else if (scwin.contnId === "input") {
                await $c.win.alert("저장/수정 후 적용됩니다.");
            } else if (dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") === js_emp_no) {
                await $c.win.alert("작성자는 파일클릭시 자동 다운로드 됩니다. \n\n입력된 비밀번호로 수정시, 저장/수정 후 적용됩니다.");
            }
        } else {
            if (filePw.getValue() !== "") {
                if (scwin.contnId !== "input" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") !== js_emp_no) {
                    await $c.win.alert("비밀번호가 올바르지 않습니다.");
                } else if (scwin.contnId === "input") {
                    await $c.win.alert("저장을 해야 적용됩니다.");
                } else if (dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") === js_emp_no) {
                    await $c.win.alert("작성자는 파일클릭시 자동 다운로드 됩니다.");
                }
            } else {
                await $c.win.alert("비밀번호를 입력해주세요");
            }
            filePw.focus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30301.btn_input_onclick" });
    }
};

