/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (dts_fileList.getCellData(1, "fileInfo") === "") {
        dts_fileList.Reset();
    }
    if (cmb_knowlg_tp.getValue().length < 1) {
        await $c.win.alert("지식구분을 선택하시오.");
        cmb_knowlg_tp.focus();
        return;
    }
    if (cmb_secu_lvl_tp.getValue().length < 1) {
        await $c.win.alert("보안수준을 선택하시오.");
        cmb_secu_lvl_tp.focus();
        return;
    }
    if (tbox_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!await scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    if (scwin.getChkValue(cbox_mail_yn) === "1" && scwin.checkFileSize() === false) {
        await $c.win.alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        return false;
    }
    let rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        tbox_wrtr_emp_nm.setValue(js_emp_no);
        dts_ShareRoomInfo.setCellData(1, "REG_DEP_CD", js_dep_cd);
        dts_ShareRoomInfo.setCellData(1, "IMPT_CONTN_YN", scwin.getChkValue(chb_impt_contn_yn));
        dts_ShareRoomInfo.setCellData(1, "MAIL_SEND_YN", scwin.getChkValue(cbox_mail_yn));
        dts_ShareRoomInfo.setCellData(1, "WRTR_EMP_EMAIL", js_inside_email);
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ShareRoom.do",
            ref : "dts_ShareRoomInfo,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

