 */
scwin.iniPicYn = function() {
    dts_fileList.setBroadcast(false);
    for (let z = 1; z < 6; z++) {
        dts_fileList.setCellData(z, "PIC_YN", "F");
    }
    dts_fileList.setBroadcast(true, true);
};

/**
 * @method
 * @name iniPicYnSet
 * @description ini Pic Yn Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.iniPicYnSet = function() {
    dts_fileList.setBroadcast(false);
    for (let z = 1; z < 6; z++) {
        if (dts_fileList.getCellData(z, "ATTACH_FILE_PW") !== "") {
            dts_fileList.setCellData(z, "PIC_YN", "T");
            scwin.pwcnt = 1;
        } else {
            dts_fileList.setCellData(z, "PIC_YN", "F");
        }
    }
    dts_fileList.setBroadcast(true, true);
};

/**
 * @method
 * @name iniAtachfFilePwSet
 * @description ini Atachf File Pw Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.iniAtachfFilePwSet = function() {
    let vcnt = 0;
    dts_fileList.setBroadcast(false);
    for (let z = 1; z < 6; z++) {
        if (dts_fileList.getCellData(z, "ATTACH_FILE_PW") !== "") {
            dts_fileList.setCellData(z, "PIC_YN", "T");
            scwin.pwcnt = 1;
            vcnt += 1;
            if (vcnt > 0) {
                filePw.show("");
                label_16.show("");
                btn_input.show("");
                filePw.setValue(dts_fileList.getCellData(z, "ATTACH_FILE_PW"));
            }
        } else {
            dts_fileList.setCellData(z, "PIC_YN", "F");
        }
    }
    dts_fileList.setBroadcast(true, true);
};

/**
 * @method
 * @name copyAttachFilePw
 * @description copy Attach File Pw 처리
 * @returns {void}
 * @hidden N
 */
scwin.copyAttachFilePw = function() {
    let vcnt = 0;
    dts_fileList.setBroadcast(false);
    for (let z = 1; z < 6; z++) {
        if (dts_fileList.getCellData(z, "PIC_YN") === "T") {
            dts_fileList.setCellData(z, "ATTACH_FILE_PW", filePw.getValue());
            scwin.pwcnt = 1;
            vcnt += 1;
        } else {
            dts_fileList.setCellData(z, "ATTACH_FILE_PW", "");
        }
    }
    dts_fileList.setBroadcast(true, true);
    if (vcnt < 1) {
        scwin.iniAttachFilePw();
        scwin.pwcnt = 0;
    }
};

/**
 * @method
 * @name chHolding
 * @description ch Holding 처리
 * @returns {void}
 * @hidden N
 */
scwin.chHolding = function() {
    if (dts_fileList.getCellData(dts_fileList.getRowPosition(), "PIC_YN") === "T") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "PIC_YN", "F");
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "PIC_YN", "T");
    }
};

/**
 * @method
 * @name canUploadFile
 * @description can Upload File 처리
 * @returns {void}
 * @hidden N
 */
scwin.canUploadFile = function() {
    let maxFileSize = 1024 * 1024 * 30; // 30MB
    const mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name checkFileSize
 * @description 전체 파일 사이즈 체크
 * @returns {void}
 * @hidden N
 */
scwin.checkFileSize = function() {
    let maxFileSize = 1024 * 30; // 30MB
    let totalFileSize = 0;
    let isValid = true;
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        totalFileSize = Number(totalFileSize) + Number(dts_fileList.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > maxFileSize) {
        // alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};

